    sell_book = []  # heap: (price, arrival_time, id, qty) - min heap
    order_map = {}  # maps id to (side, price, qty, arrival_time, is_cancelled)
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, qty, at, is_cancelled = order_map[order_id]
                if not is_cancelled:
                    order_map[order_id] = (side, price, qty, at, True)

